static_assert(sizeof(kIcons)/sizeof(kIcons[0]) == static_cast<std::size_t>(IconId::Count));
[[nodiscard]] constexpr const GlyphView* icon(IconId id, int opticalMaster = 24) noexcept {
    const auto index = static_cast<std::size_t>(id);
    if (index >= static_cast<std::size_t>(IconId::Count)) return nullptr;
    const auto& item = kIcons[index];
    const auto viewIndex = opticalMaster <= 12 && item.micro >= 0 ? item.micro : opticalMaster < 24 ? item.compact : item.regular;
    return &kViews[viewIndex];
}
// Convenience for setup/tests only. Runtime widgets cache IconId, not names.
[[nodiscard]] constexpr const GlyphView* findIcon(std::string_view name, int master = 24) noexcept {
    for (std::size_t i = 0; i < static_cast<std::size_t>(IconId::Count); ++i)
        if (name == kIcons[i].name) return icon(static_cast<IconId>(i), master);
    return nullptr;
}
